/**
 * Resolve the preset a cell composes from, before any agent exists. A roster
 * the composition does not hold, and a preset it does not supply or reports
 * broken, both fail here rather than inside the agent factory's `setup`,
 * where the refusal would already have cost a workspace and a fixture
 * overlay. A run that names no preset resolves nothing and mounts nothing.
 * @param preset - the preset the request named, absent for a run that named none.
 * @throws {@link EnvironmentRunError} when no roster is composed, or the
 *   roster cannot supply the named preset.
 */
private async requirePreset(preset: string | undefined): Promise<void> {
  if (preset === undefined) return
  const presets = this.ctx.get('agentPresets')
  if (presets === undefined) {
    throw new EnvironmentRunError(`agent preset "${preset}" is unavailable: this composition has no agent preset roster`, 'ENVIRONMENT_RUN_PRESET_UNAVAILABLE')
  }
  let resolved
  try {
    resolved = await presets.resolve(preset)
  } catch (error: unknown) {
    throw new EnvironmentRunError(`agent preset "${preset}" cannot compose a cell: ${error instanceof Error ? error.message : String(error)}`, 'ENVIRONMENT_RUN_UNKNOWN_PRESET')
  }
  if (resolved.broken !== undefined) {
    throw new EnvironmentRunError(`agent preset "${preset}" cannot compose a cell: ${resolved.broken}`, 'ENVIRONMENT_RUN_UNKNOWN_PRESET')
  }
}

